package com.nivor.notification;import com.nivor.notification.NotificationDtos.*;import java.util.List;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/notifications")public class NotificationController{private final NotificationService service;public NotificationController(NotificationService s){service=s;}@GetMapping public List<View> list(@AuthenticationPrincipal UserDetails u,@RequestParam(defaultValue="false")boolean unreadOnly){return service.list(u.getUsername(),unreadOnly);}@GetMapping("/unread-count")public UnreadCount count(@AuthenticationPrincipal UserDetails u){return service.count(u.getUsername());}@PatchMapping("/{id}/read")public View read(@AuthenticationPrincipal UserDetails u,@PathVariable long id){return service.read(u.getUsername(),id);}@PatchMapping("/read-all")public java.util.Map<String,Long> readAll(@AuthenticationPrincipal UserDetails u){return java.util.Map.of("updated",service.readAll(u.getUsername()));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserDetails u,@PathVariable long id){service.delete(u.getUsername(),id);return ResponseEntity.noContent().build();}}
